const recalculateDeliveryRunCounters = `-- name: RecalculateDeliveryRunCounters :one
UPDATE delivery_runs r
SET planned_stops = c.total, completed_stops = c.completed,
    delivered_count = c.delivered, failed_count = c.failed,
    cod_expected_minor = c.cod_expected, cod_collected_minor = c.cod_collected
FROM (
    SELECT count(*) FILTER (WHERE status <> 'REMOVED') AS total,
           count(*) FILTER (WHERE status IN ('DELIVERED','FAILED','RETURNED_TO_BRANCH')) AS completed,
           count(*) FILTER (WHERE status = 'DELIVERED') AS delivered,
           count(*) FILTER (WHERE status = 'FAILED') AS failed,
           COALESCE(sum(cod_amount_minor) FILTER (WHERE status <> 'REMOVED'), 0)::bigint AS cod_expected,
           COALESCE(sum(cod_collected_minor), 0)::bigint AS cod_collected
    FROM delivery_run_items WHERE delivery_run_id = $1
) c
WHERE r.id = $1
RETURNING r.id, r.public_id, r.organization_id, r.run_code, r.branch_id, r.agent_user_id, r.run_date, r.status, r.vehicle_reference, r.planned_stops, r.completed_stops, r.delivered_count, r.failed_count, r.cod_expected_minor, r.cod_collected_minor, r.currency, r.dispatched_at, r.dispatched_by_user_id, r.started_at, r.completed_at, r.closed_at, r.closed_by_user_id, r.cancelled_at, r.cancellation_reason, r.created_by_user_id, r.metadata, r.created_at, r.updated_at, r.version
`

