const updateDeliveryRunItemStatus = `-- name: UpdateDeliveryRunItemStatus :one
UPDATE delivery_run_items
SET status = $1,
    dispatched_at = CASE WHEN $1::text = 'OUT_FOR_DELIVERY'
                         THEN COALESCE(dispatched_at, now()) ELSE dispatched_at END,
    completed_at = CASE WHEN $1::text IN ('DELIVERED','FAILED','RETURNED_TO_BRANCH')
                        THEN now() ELSE completed_at END,
    cod_collected_minor = COALESCE($2, cod_collected_minor),
    attempt_count = attempt_count + $3::int,
    removed_at = CASE WHEN $1::text = 'REMOVED' THEN now() ELSE removed_at END,
    removal_reason = COALESCE($4, removal_reason)
WHERE id = $5
RETURNING id, public_id, organization_id, delivery_run_id, shipment_id, stop_sequence, status, delivery_type, cod_amount_minor, cod_collected_minor, added_at, added_by_user_id, dispatched_at, completed_at, removed_at, removal_reason, attempt_count
`

